try{
 if($_SERVER['REQUEST_METHOD']==='POST'){
  $action=$_POST['action']??'';$eid=(int)($_POST['employee_id']??$eid);
  if($action==='add_contract'){
   $type=$_POST['contract_type']??'permanent';$start=$_POST['start_date']??'';$end=$_POST['end_date']!==''?($_POST['end_date']??null):null;$salary=(float)($_POST['basic_salary']??0);$currency=strtoupper(trim($_POST['salary_currency']??'EGP'));$frequency=$_POST['pay_frequency']??'monthly';$prob=$_POST['probation_end_date']!==''?($_POST['probation_end_date']??null):null;$number=trim($_POST['contract_number']??'')?:null;$notes=trim($_POST['notes']??'')?:null;$hours=($_POST['working_hours_per_week']??'')!==''?(float)$_POST['working_hours_per_week']:null;
   if(!isset($types[$type])||!isset($freq[$frequency]))throw new InvalidArgumentException('بيانات العقد غير صالحة.');if(!$start)throw new InvalidArgumentException('تاريخ بداية العقد مطلوب.');if(!preg_match('/^[A-Z]{3}$/',$currency))throw new InvalidArgumentException('رمز العملة يجب أن يتكون من 3 أحرف.');
   $path=null;if(isset($_FILES['contract_file'])&&$_FILES['contract_file']['error']!==UPLOAD_ERR_NO_FILE){if($_FILES['contract_file']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('تعذر رفع ملف العقد.');$f=$_FILES['contract_file'];if($f['size']>10*1024*1024)throw new RuntimeException('حجم الملف يتجاوز 10 ميجابايت.');$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if(!in_array($ext,['pdf','jpg','jpeg','png'],true))throw new RuntimeException('صيغة الملف غير مدعومة.');$dir=__DIR__.'/../../storage/hr_contracts/';if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('تعذر إنشاء مجلد ملفات العقود.');$name='contract_'.$eid.'_'.time().'_'.bin2hex(random_bytes(3)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.$name))throw new RuntimeException('تعذر حفظ ملف العقد.');$path='storage/hr_contracts/'.$name;}
   $cid=hrCreateEmployeeContract($eid,$type,$start,$end,$salary,$currency,$frequency,$number,$prob,$path,$notes,Session::getUserID());if($hours!==null)$pdo->prepare('UPDATE hr_employee_contracts SET working_hours_per_week=? WHERE id=?')->execute([$hours,$cid]);
   if($start<=date('Y-m-d'))hrChangeEmployeeSalary($eid,$salary,$start,'contract_change',Session::getUserID(),'تم إنشاء سجل الراتب من عقد جديد',$cid,$currency,$frequency);$msg='تم إنشاء العقد وتحديث سجل الراتب بنجاح.';$view='contracts';
  }elseif($action==='change_salary'){
   $salary=(float)($_POST['basic_salary']??0);$effective=$_POST['effective_from']??'';$reason=$_POST['reason']??'adjustment';$notes=trim($_POST['salary_notes']??'')?:null;$cid=(int)($_POST['contract_id']??0)?:null;$currency=strtoupper(trim($_POST['salary_currency']??'EGP'));$frequency=$_POST['pay_frequency']??'monthly';
   hrChangeEmployeeSalary($eid,$salary,$effective,$reason,Session::getUserID(),$notes,$cid,$currency,$frequency);$msg='تم حفظ تغيير الراتب في السجل التاريخي وتحديث الراتب الحالي عند سريان التغيير.';$view='salary';
  }elseif($action==='contract_status'){
   $cid=(int)($_POST['contract_id']??0);$new=$_POST['status']??'';$c=hrGetEmployeeContract($cid);if(!$c)throw new RuntimeException('العقد غير موجود.');if(!in_array($new,['active','terminated','cancelled'],true))throw new InvalidArgumentException('حالة العقد غير صالحة.');
   if($new==='active'){$pdo->beginTransaction();try{$pdo->prepare("UPDATE hr_employee_contracts SET status='expired' WHERE employee_id=? AND id<>? AND status='active'")->execute([$c['employee_id'],$cid]);$pdo->prepare("UPDATE hr_employee_contracts SET status='active' WHERE id=?")->execute([$cid]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}if((int)$c['employee_id']===$eid&&$c['start_date']<=date('Y-m-d'))hrChangeEmployeeSalary($eid,(float)$c['basic_salary'],$c['start_date'],'contract_change',Session::getUserID(),'تم تفعيل العقد',$cid,$c['salary_currency'],$c['pay_frequency']);$msg='تم تفعيل العقد.';}else{$pdo->prepare('UPDATE hr_employee_contracts SET status=? WHERE id=?')->execute([$new,$cid]);$msg=$new==='terminated'?'تم إنهاء العقد.':'تم إلغاء العقد.';}
  }
 }
}catch(Throwable $e){$msg=$e->getMessage();$err=true;}
$employees=dbFetchAll("SELECT e.id,e.employee_code,e.full_name,e.position,e.basic_salary,d.name_ar dept_name FROM employees e LEFT JOIN departments d ON d.id=e.department_id ORDER BY e.full_name",[]);
$emp=null;$contracts=[];$history=[];if($eid){$emp=dbFetchOne("SELECT e.*,d.name_ar dept_name,s.name_ar state_name FROM employees e LEFT JOIN departments d ON d.id=e.department_id LEFT JOIN hr_employment_states s ON s.id=e.employment_state_id WHERE e.id=?",[$eid]);if($emp){$contracts=dbFetchAll("SELECT * FROM hr_employee_contracts WHERE employee_id=? ORDER BY start_date DESC,id DESC",[$eid]);$history=hrGetEmployeeSalaryHistory($eid);}}
